using System;
using System.Collections.Generic;

public class AIVLoader
{
	[Serializable]
	public class Frame
	{
		public int itemType;

		public List<int> tilePositionOfsets;

		public bool shouldPause;
	}

	[Serializable]
	public struct MiscItemDefinition
	{
		public int positionOfset;

		public int itemType;

		public int number;
	}

	[Serializable]
	public class SaveData
	{
		public int pauseDelayAmount;

		public List<Frame> frames;

		public List<MiscItemDefinition> miscItems;

		public short[] GetRawData()
		{
			List<short> list = new List<short>();
			list.Add((short)pauseDelayAmount);
			List<short> list2 = new List<short>();
			list2.Add(0);
			short num = 2;
			foreach (Frame frame in frames)
			{
				if (frame.shouldPause)
				{
					list2.Add(num);
				}
				num++;
				if (list2.Count >= 50)
				{
					break;
				}
			}
			list.Add((short)list2.Count);
			list.AddRange(list2);
			list.Add((short)frames.Count);
			foreach (Frame frame2 in frames)
			{
				if (frame2.tilePositionOfsets.Count == 1)
				{
					list.Add((short)frame2.itemType);
					list.Add((short)frame2.tilePositionOfsets[0]);
					continue;
				}
				list.Add((short)(-frame2.itemType));
				list.Add((short)frame2.tilePositionOfsets.Count);
				foreach (int tilePositionOfset in frame2.tilePositionOfsets)
				{
					list.Add((short)tilePositionOfset);
				}
			}
			list.Add((short)miscItems.Count);
			foreach (MiscItemDefinition miscItem in miscItems)
			{
				int num2 = miscItem.itemType;
				if (num2 > 9000)
				{
					num2 -= 9000;
				}
				list.Add((short)num2);
				list.Add((short)miscItem.positionOfset);
				list.Add((short)miscItem.number);
			}
			return list.ToArray();
		}
	}

