	public static void UploadDefaultAIV(int lordType, int playerID, bool evreySkirmishSet = false, bool evreyHistoricalSet = false)
	{
		int num = 8;
		if (evreyHistoricalSet)
		{
			num = 1;
		}
		for (int i = 0; i < num; i++)
		{
			short[] aIVData = getAIVData(lordType, i, evreySkirmishSet, evreyHistoricalSet);
			EngineInterface.ImportAIV(playerID - 1, i, aIVData, 0);
		}
	}
